/* Generated by Antigravity AI - Adhering to SOLID & Design Patterns */

import { Fragment } from "react";
import { Image as ImageIcon } from "lucide-react";
import { IArticleFormData } from "../admin-articles.types";
import { getApiBaseUrl } from "@/lib/api-url";

interface CategoryNode {
  _id: string;
  name: string;
  type?: string;
  children?: CategoryNode[];
}

interface Props {
  formData: IArticleFormData;
  setFormData: (data: IArticleFormData | ((prev: IArticleFormData) => IArticleFormData)) => void;
  categories: CategoryNode[];
}

export function ArticleEditorSettingsComponent({
  formData,
  setFormData,
  categories,
}: Props) {
  const renderCategoryOptions = (nodes: CategoryNode[], level = 0) => {
    return nodes.map((node) => {
      const indent = "— ".repeat(level);
      return (
        <Fragment key={node._id}>
          <option value={node._id}>
            {indent} {node.name}
          </option>
          {node.children &&
            node.children.length > 0 &&
            renderCategoryOptions(node.children, level + 1)}
        </Fragment>
      );
    });
  };

  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-slate-900 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 space-y-4">
        <h2 className="text-lg font-bold text-gray-900 dark:text-gray-100 border-b pb-2 mb-4">
          Thuộc Tính
        </h2>

        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
            Trạng thái xuất bản
          </label>
          <select
            value={formData.isPublished ? "true" : "false"}
            onChange={(e) =>
              setFormData({
                ...formData,
                isPublished: e.target.value === "true",
              })
            }
            className="w-full px-4 py-2 dark:bg-slate-800 dark:border-slate-700 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-sm font-medium"
          >
            <option value="true">Đã xuất bản (Public)</option>
            <option value="false">Lưu nháp (Draft)</option>
          </select>
        </div>

        <div className="flex items-center gap-2 mt-4">
          <input
            type="checkbox"
            id="isPinned"
            checked={formData.isPinned}
            onChange={(e) =>
              setFormData({ ...formData, isPinned: e.target.checked })
            }
            className="w-4 h-4 text-blue-600 border-gray-300 dark:border-slate-700 rounded focus:ring-blue-500"
          />
          <label
            htmlFor="isPinned"
            className="text-sm font-semibold text-gray-700 dark:text-gray-200"
          >
            Ghim bài viết này lên đầu danh mục
          </label>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
            Danh mục CMS (Liên kết Tree) <span className="text-red-500">*</span>
          </label>
          <select
            required
            value={formData.categoryId}
            onChange={(e) =>
              setFormData({ ...formData, categoryId: e.target.value })
            }
            className="w-full px-4 py-2 dark:bg-slate-800 dark:border-slate-700 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          >
            <option value="NONE">-- Không liên kết --</option>
            <optgroup label="DỊCH VỤ & GIẢI PHÁP (SERVICE)">
              {renderCategoryOptions(
                categories.filter((c) => c.type === "SERVICE"),
              )}
            </optgroup>
            <optgroup label="BÀI VIẾT & CẨM NANG (POST)">
              {renderCategoryOptions(
                categories.filter((c) => c.type === "POST"),
              )}
            </optgroup>
            <optgroup label="GIỚI THIỆU (ABOUT)">
              {renderCategoryOptions(
                categories.filter((c) => c.type === "ABOUT"),
              )}
            </optgroup>
          </select>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900/50 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 space-y-4">
        <h2 className="text-lg font-bold text-gray-900 dark:text-gray-100 border-b pb-2 mb-4">
          Ảnh Đại Diện
        </h2>

        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
            URL Ảnh hoặc Tải lên
          </label>
          <div className="flex gap-2 mb-3">
            <input
              type="text"
              value={formData.thumbnail}
              onChange={(e) =>
                setFormData({ ...formData, thumbnail: e.target.value })
              }
              className="flex-1 px-4 py-2 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-sm"
              placeholder="https://example.com/image.jpg"
            />
            <label className="cursor-pointer bg-blue-50 hover:bg-blue-100 text-blue-600 px-4 py-2 rounded-xl flex items-center justify-center font-medium text-sm transition-colors">
              <span>Tải lên</span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={async (e) => {
                  const file = e.target.files?.[0];
                  if (!file) return;
                  try {
                    const uploadData = new FormData();
                    uploadData.append("file", file);
                    const API_URL = getApiBaseUrl();
                    const res = await fetch(`${API_URL}/upload/image`, {
                      method: "POST",
                      body: uploadData,
                    });
                    const data = await res.json();
                    const thumbnailUrl = data.url?.startsWith("http://") || data.url?.startsWith("https://")
                      ? data.url
                      : `${API_URL}${data.url}`;
                    setFormData((prev) => ({ ...prev, thumbnail: thumbnailUrl }));
                  } catch (error) {
                    console.error("Upload failed", error);
                    alert("Tải ảnh thất bại!");
                  }
                }}
              />
            </label>
          </div>
          {formData.thumbnail ? (
            <div className="aspect-video w-full rounded-xl overflow-hidden border border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800/50 flex items-center justify-center">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={formData.thumbnail}
                alt="Thumbnail preview"
                className="w-full h-full object-cover"
                onError={(e) => {
                  (e.target as HTMLImageElement).src =
                    "https://placehold.co/600x400?text=L%E1%BB%97i+%E1%BA%A3nh";
                }}
              />
            </div>
          ) : (
            <div className="aspect-video w-full rounded-xl border-2 border-dashed border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800/50 flex flex-col items-center justify-center text-gray-400">
              <ImageIcon size={32} className="mb-2" />
              <span className="text-xs">Chưa có ảnh đại diện</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
